Register Individual.code:
// Register a new individual (e.g. from a field enrolment form).
// openspp operations don't resolve $ references, so call them inside fn() with state values.
fn(state =>
  createIndividual({
    name: state.data.fullName, // e.g. 'Amina Diallo'
    birthdate: state.data.dateOfBirth, // 'YYYY-MM-DD'
    gender: state.data.gender,
    phone: state.data.phone,
    address: state.data.village,
  })(state)
);

Register Household Group.code:
// Register a household as a group registrant.
// openspp operations don't resolve $ references, so call them inside fn() with state values.
fn(state =>
  createGroup({
    name: `${state.data.headOfHousehold} Household`,
    phone: state.data.phone,
    address: state.data.village,
  })(state)
);

Add Member To Household.code:
// Link an individual to a household group.
// openspp operations don't resolve $ references, so call them inside fn() with state values.
fn(state =>
  addToGroup(
    // 1) Group spp_id.
    state.data.groupSppId,
    // 2) Individual spp_id.
    state.data.individualSppId,
    // 3) Optional role in the group.
    'Head'
  )(state)
);

Update Individual.code:
// Update an individual's contact details.
// openspp operations don't resolve $ references, so call them inside fn() with state values.
fn(state =>
  updateIndividual(
    // 1) Individual spp_id.
    state.data.individualSppId,
    // 2) Fields to change.
    {
      phone: state.data.newPhone,
      address: state.data.newAddress,
    }
  )(state)
);

Enroll In Program.code:
// Enrol a registrant in a programme, e.g. a cash transfer.
// openspp operations don't resolve $ references, so call them inside fn() with state values.
fn(state =>
  enroll(
    // 1) Registrant spp_id (individual or group).
    state.data.sppId,
    // 2) Programme id.
    state.data.programId // e.g. 'PROG_2023_00000001'
  )(state)
);

Unenroll From Program.code:
// Exit a registrant from a programme.
// openspp operations don't resolve $ references, so call them inside fn() with state values.
fn(state =>
  unenroll(
    // 1) Registrant spp_id.
    state.data.sppId,
    // 2) Programme id.
    state.data.programId
  )(state)
);

Search Individuals.code:
// Find individuals by phone number.
// openspp operations don't resolve $ references, so call them inside fn() with state values.
fn(state =>
  searchIndividual(
    // 1) Domain: list of [field, operator, value] conditions.
    [['phone', '=', state.data.phone]],
    // 2) Options: limit, offset, order.
    { limit: 10 }
  )(state)
);

Get Individual.code:
// Fetch an individual by spp_id.
// openspp operations don't resolve $ references, so call them inside fn() with state values.
fn(state => getIndividual(state.data.individualSppId)(state)); // e.g. 'IND_Q4VGGZPF'

Get Household Members.code:
// List the members of a household group.
// openspp operations don't resolve $ references, so call them inside fn() with state values.
fn(state =>
  getGroupMembers(
    // 1) Group spp_id.
    state.data.groupSppId,
    // 2) Options: limit, offset, order.
    { limit: 50 }
  )(state)
