// Check which programmes a registrant is enrolled in.
// openspp operations don't resolve $ references, so call them inside fn() with state values.
fn(state => getEnrolledPrograms(state.data.sppId)(state));

Search Areas.code:
// Find an area by its code.
// openspp operations don't resolve $ references, so call them inside fn() with state values.
fn(state => searchArea([['code', '=', state.data.districtCode]])(state));
